/** Private UUID database, fake vault/transports only. No JobScheduler or remote requests. */
@RunWith(AndroidJUnit4.class)
public class AutomationStorageTest {
    private Context context;private String name;private AutomationStore store;private final long now=1_000_000;
    private final AutomationStore.Vault vault=new AutomationStore.Vault(){public String seal(String s){return "sealed:"+android.util.Base64.encodeToString(s.getBytes(java.nio.charset.StandardCharsets.UTF_8),android.util.Base64.NO_WRAP);}public String open(String s){return new String(android.util.Base64.decode(s.substring(7),android.util.Base64.NO_WRAP),java.nio.charset.StandardCharsets.UTF_8);}};
    @Before public void open(){context=InstrumentationRegistry.getInstrumentation().getTargetContext();name="automation-test-"+UUID.randomUUID()+".db";store=new AutomationStore(context,name,vault);}
    @After public void close(){if(store!=null)store.close();context.deleteDatabase(name);}
    private AutomationRule draft(boolean enabled){return new AutomationRule(UUID.randomUUID().toString(),"My webhook",AutomationEvent.Kind.TRACKING_STARTED,AutomationRule.Transport.WEBHOOK,enabled,0,"https://example.org/private?key=private-token","","","bearer-secret");}
    private AutomationEvent event(String occurrence){return AutomationEvent.occurrence(AutomationEvent.Kind.TRACKING_STARTED,occurrence,now,false);}
    @Test public void emptyAndDisabledRulesNeverQueue()throws Exception{assertTrue(store.rows().isEmpty());assertEquals(0,store.enqueue(event("one"),null));store.save(draft(false));assertEquals(0,store.enqueue(event("two"),null));assertEquals(-1,store.due());}
    @Test public void configReopensWithoutPlaintextCredentialsInRows()throws Exception{AutomationRule saved=store.save(draft(true));try(Cursor c=store.getReadableDatabase().rawQuery("SELECT config FROM rules",null)){assertTrue(c.moveToFirst());assertFalse(c.getString(0).contains("bearer-secret"));assertFalse(c.getString(0).contains("private-token"));}store.close();store=new AutomationStore(context,name,vault);AutomationRule read=store.rule(saved.id);assertEquals("bearer-secret",read.secret);assertEquals(saved.destination,read.destination);assertTrue(read.enabled);assertEquals(1,read.revision);new RuleJourney().run();}
    @Test public void eventDeduplicationSurvivesSuccessAndReopen()throws Exception{AutomationRule rule=store.save(draft(true));assertEquals(1,store.enqueue(event("same"),null));assertEquals(0,store.enqueue(event("same"),null));AtomicInteger sends=new AtomicInteger();assertTrue(AutomationDispatch.next(store,(r,e)->{assertEquals(rule.id,r.id);sends.incrementAndGet();},now,()->now,()->false));store.close();store=new AutomationStore(context,name,vault);assertEquals(0,store.enqueue(event("same"),null));assertEquals(-1,store.due());assertEquals(1,sends.get());assertEquals("Delivered",store.rows().get(0).status);}
    @Test public void offAndEditCancelPendingWithoutReplayingIt()throws Exception{AutomationRule rule=store.save(draft(true));store.enqueue(event("one"),null);store.enabled(rule.id,rule.revision,false);assertEquals(-1,store.due());assertFalse(store.rule(rule.id).enabled);store.enabled(rule.id,2,true);assertEquals(-1,store.due());store.enqueue(event("two"),null);AutomationRule edit=store.rule(rule.id);store.save(edit);assertEquals(-1,store.due());assertEquals(4,store.rule(rule.id).revision);}
    @Test public void staleSaveAndVaultFailurePreserveCurrentRule()throws Exception{AutomationRule rule=store.save(draft(true));try{store.save(rule.revision(0));fail();}catch(IllegalStateException expected){}store.close();store=new AutomationStore(context,name,new AutomationStore.Vault(){public String seal(String s)throws Exception{throw new Exception("locked");}public String open(String s)throws Exception{return vault.open(s);}});try{store.save(rule.enabled(false));fail();}catch(Exception expected){}assertTrue(store.rule(rule.id).enabled);assertEquals(1,store.rule(rule.id).revision);}
    @Test public void retriesPersistAndStopAtSixAttempts()throws Exception{store.save(draft(true));store.enqueue(event("retry"),null);AtomicInteger calls=new AtomicInteger();for(int n=0;n<6;n++){long due=store.due();assertTrue(due>0);long instant=due;assertTrue(AutomationDispatch.next(store,(r,e)->{calls.incrementAndGet();throw new AutomationDelivery.Failure("Webhook could not connect",true);},instant,()->instant,()->false));store.close();store=new AutomationStore(context,name,vault);}assertEquals(6,calls.get());assertEquals(-1,store.due());assertEquals("Webhook could not connect",store.rows().get(0).status);}
    @Test public void expiryPermanentErrorAndCancellationDoNotSend()throws Exception{AutomationRule rule=store.save(draft(true));store.enqueue(event("expired"),null);AtomicInteger sends=new AtomicInteger();assertTrue(AutomationDispatch.next(store,(r,e)->sends.incrementAndGet(),now+AutomationDelivery.MAX_AGE,()->now+AutomationDelivery.MAX_AGE,()->false));assertEquals(0,sends.get());assertEquals("Event expired",store.rows().get(0).status);store.enqueue(event("cancel"),null);assertFalse(AutomationDispatch.next(store,(r,e)->sends.incrementAndGet(),now,()->now,()->true));assertEquals(now,store.due());assertTrue(AutomationDispatch.next(store,(r,e)->{throw new AutomationDelivery.Failure("Webhook HTTP 403",false);},now,()->now,()->false));assertEquals(-1,store.due());assertTrue(store.rule(rule.id).enabled);}
    @Test public void queueBoundAndDeletionAreDurable()throws Exception{AutomationRule rule=store.save(draft(true));for(int n=0;n<101;n++)store.enqueue(event("event"+n),null);try(Cursor c=store.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM deliveries WHERE state='pending'",null)){c.moveToFirst();assertEquals(100,c.getInt(0));}assertEquals("Queue full; event not queued",store.rows().get(0).status);store.delete(rule.id);assertTrue(store.rows().isEmpty());assertEquals(-1,store.due());}
    @Test public void targetedTestCannotFanOutToOtherRules()throws Exception{AutomationRule first=store.save(draft(true));store.save(draft(true));AutomationEvent test=AutomationEvent.occurrence(AutomationEvent.Kind.TRACKING_STARTED,"test",now,true);assertEquals(1,store.enqueue(test,first.id));assertEquals(first.id,store.next(now).rule);assertTrue(store.next(now).event.test);}
    @Test public void disablingDuringAttemptDoesNotReviveRemovedQueue()throws Exception{AutomationRule rule=store.save(draft(true));store.enqueue(event("inflight"),null);assertTrue(AutomationDispatch.next(store,(r,e)->store.enabled(r.id,r.revision,false),now,()->now,()->false));assertEquals(-1,store.due());assertEquals("Off",store.rows().get(0).status);assertFalse(store.rule(rule.id).enabled);}

    /** App UI and real private SQLite only; the fake scheduler never delivers anything. */
    private final class RuleJourney {
        final Instrumentation i=InstrumentationRegistry.getInstrumentation();final UiDevice device=UiDevice.getInstance(i);
        final List<AutomationActivity> activities=new ArrayList<>();final AtomicBoolean blockOpen=new AtomicBoolean(),failOpen=new AtomicBoolean(),blockSchedule=new AtomicBoolean(),failSchedule=new AtomicBoolean();
        final CountDownLatch readStarted=new CountDownLatch(1),readRelease=new CountDownLatch(1),scheduleStarted=new CountDownLatch(1),scheduleRelease=new CountDownLatch(1);
        final AtomicInteger schedules=new AtomicInteger(),recoveries=new AtomicInteger();
        AutomationActivity activity;String step="automation UI admission";int captures;
        final AutomationActivity.Port fixture=new AutomationActivity.Port(){
            public AutomationStore open(Context app)throws Exception{assertSame(context.getApplicationContext(),app);if(blockOpen.compareAndSet(true,false)){readStarted.countDown();assertTrue("Release private reader",readRelease.await(15,TimeUnit.SECONDS));}if(failOpen.compareAndSet(true,false))throw new IllegalStateException("Private fixture read unavailable");return new AutomationStore(app,name,vault);}
            public AutomationStore.Vault vault(){return vault;}
            public String status(Context app){return "";}
            public void recover(Context app){assertSame(context.getApplicationContext(),app);recoveries.incrementAndGet();}
            public void schedule(Context app,AutomationStore privateStore)throws Exception{assertSame(context.getApplicationContext(),app);assertEquals(name,privateStore.getDatabaseName());schedules.incrementAndGet();if(blockSchedule.compareAndSet(true,false)){scheduleStarted.countDown();assertTrue("Release accepted private operation",scheduleRelease.await(15,TimeUnit.SECONDS));}if(failSchedule.compareAndSet(true,false))throw new IllegalStateException("Private fixture scheduling unavailable");}
        };
        void await(BooleanSupplier condition)throws Exception{long until=SystemClock.elapsedRealtime()+8000;while(SystemClock.elapsedRealtime()<until){if(condition.getAsBoolean())return;Thread.sleep(20);}assertTrue(step,condition.getAsBoolean());}
        Object field(String key){try{java.lang.reflect.Field f=AutomationActivity.class.getDeclaredField(key);f.setAccessible(true);return f.get(activity);}catch(Exception error){throw new AssertionError(error);}}
        void quiet(){assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(MicrophoneLease.occupied());assertNull(SleepSoundService.snapshot());assertFalse(Prefs.flag(context,"ringing"));assertFalse(Prefs.flag(context,"tracking"));}
        void privateOwner(){assertSame(fixture,AutomationActivity.port);assertSame(fixture,field("owner"));assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertTrue(activity.getIntent().getBooleanExtra("visualReview",false));quiet();}
        View focused(){if(activity==null||activity.isDestroyed()||activity.isFinishing())return null;Dialog dialog=(Dialog)field("ownedDialog");if(!((String)field("confirmation")).isEmpty()&&(dialog==null||!dialog.isShowing()))return null;View expected=dialog!=null&&dialog.isShowing()?dialog.getWindow().getDecorView():activity.getWindow().getDecorView();View result=null;for(View root:WindowInspector.getGlobalWindowViews())if(root.getContext().getPackageName().equals(context.getPackageName())&&root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isLaidOut()){assertNull("One owned focused window",result);result=root;}return result==expected?result:null;}
        View find(View view,String text,boolean description){if(description?text.contentEquals(view.getContentDescription()==null?"":view.getContentDescription()):view instanceof TextView&&text.contentEquals(((TextView)view).getText()))return view;if(view instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View result=find(group.getChildAt(n),text,description);if(result!=null)return result;}return null;}
        View ready()throws Exception{View[] root={null};await(()->{i.runOnMainSync(()->root[0]=activity==null||activity.isDestroyed()||activity.isFinishing()?null:focused());return root[0]!=null;});i.runOnMainSync(this::privateOwner);return root[0];}
        void require(String text)throws Exception{step="require "+text;await(()->{boolean[] found={false};i.runOnMainSync(()->{View root=focused();found[0]=root!=null&&find(root,text,false)!=null;});return found[0];});}
        Rect bounds(View root,String text,boolean description,boolean enabled){View view=find(root,text,description);assertNotNull(text,view);while(!view.isClickable()&&view.getParent() instanceof View)view=(View)view.getParent();assertTrue(text+" actual action",view.isClickable());if(enabled)assertTrue(text+" enabled",view.isEnabled());Rect visible=new Rect();assertTrue(view.getGlobalVisibleRect(visible));assertEquals(view.getWidth(),visible.width());assertEquals(view.getHeight(),visible.height());assertTrue(visible.width()>=Design.dp(context,48)&&visible.height()>=Design.dp(context,48));int[] at=new int[2];view.getLocationOnScreen(at);Rect screen=new Rect(at[0],at[1],at[0]+view.getWidth(),at[1]+view.getHeight());View decor=activity.getWindow().getDecorView();int[] origin=new int[2];decor.getLocationOnScreen(origin);assertTrue(text+" above gesture dock",screen.bottom<=origin[1]+decor.getHeight()-decor.getRootWindowInsets().getInsets(WindowInsets.Type.navigationBars()).bottom);return screen;}
        void frame(View root)throws Exception{CountDownLatch committed=new CountDownLatch(1);i.runOnMainSync(()->{assertSame(root,focused());assertTrue(root.isHardwareAccelerated());root.getViewTreeObserver().registerFrameCommitCallback(committed::countDown);root.invalidate();});assertTrue(step+" committed native frame",committed.await(5,TimeUnit.SECONDS));i.runOnMainSync(()->assertSame(root,focused()));}
        void tap(String text,boolean description)throws Exception{
            step="single private native action "+text;ready();View[] committedOwner={null};await(()->{boolean[] shown={false};i.runOnMainSync(()->{View root=focused();if(root==null)return;View v=find(root,text,description);if(v==null)return;while(!v.isClickable()&&v.getParent() instanceof View)v=(View)v.getParent();v.requestRectangleOnScreen(new Rect(0,0,v.getWidth(),v.getHeight()),true);Rect visible=new Rect();shown[0]=v.isEnabled()&&v.isClickable()&&v.getGlobalVisibleRect(visible)&&visible.width()==v.getWidth()&&visible.height()==v.getHeight();if(shown[0])committedOwner[0]=root;});return shown[0];});
            View root=committedOwner[0];frame(root);Rect[] target={null};i.runOnMainSync(()->{privateOwner();target[0]=bounds(root,text,description,true);});assertTrue(device.click(target[0].centerX(),target[0].centerY()));i.waitForIdleSync();ready();
        }
        void click(String text)throws Exception{tap(text,false);}void desc(String text)throws Exception{tap(text,true);}
        void text(String label,String value)throws Exception{desc(label);UiObject2 input=device.findObject(By.desc(label));assertNotNull(label,input);input.setText(value);i.waitForIdleSync();assertText(label,value);boolean[] ime={false};i.runOnMainSync(()->ime[0]=activity.getWindow().getDecorView().getRootWindowInsets().isVisible(WindowInsets.Type.ime()));if(ime[0]){assertTrue(device.pressBack());i.waitForIdleSync();ready();}}
        void assertText(String label,String expected)throws Exception{i.runOnMainSync(()->{View input=find(activity.getWindow().getDecorView(),label,true);assertTrue(input instanceof EditText);assertEquals(expected,((EditText)input).getText().toString());});}
        void ruleState(boolean expected)throws Exception{step="private persisted rule enabled="+expected;await(()->{boolean[] current={false};i.runOnMainSync(()->{View root=focused();View toggle=root==null?null:find(root,"Rule enabled: My webhook",true);current[0]=field("request")==null&&!(boolean)field("loading")&&toggle instanceof Switch&&toggle.isEnabled()&&((Switch)toggle).isChecked()==expected;});return current[0];});}
        void page(String expected)throws Exception{await(()->{boolean[] same={false};i.runOnMainSync(()->same[0]=expected.equals(field("page")));return same[0];});}
        void back()throws Exception{ready();assertTrue(device.pressBack());i.waitForIdleSync();ready();}
        void launch()throws Exception{activity=(AutomationActivity)i.startActivitySync(new Intent(context,AutomationActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("visualReview",true).putExtra("verificationLabel","CI private rules · fake scheduling · no delivery"));activities.add(activity);ready();}
        void recreate()throws Exception{AutomationActivity before=activity;Instrumentation.ActivityMonitor monitor=i.addMonitor(AutomationActivity.class.getName(),null,false);try{i.runOnMainSync(before::recreate);activity=(AutomationActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);activities.add(activity);}finally{i.removeMonitor(monitor);}await(before::isDestroyed);ready();}
        void capture(String suffix,String action,boolean enabled)throws Exception{step="capture "+suffix;assertTrue(captures<10);View root=ready();frame(root);if(action!=null)i.runOnMainSync(()->bounds(root,action,false,enabled));File folder=new File(context.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,suffix+".png")));captures++;}
        int pending(){try(Cursor c=store.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM deliveries WHERE state='pending'",null)){assertTrue(c.moveToFirst());return c.getInt(0);}}
        void run()throws Exception{
            assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());quiet();AutomationActivity.Port previous=AutomationActivity.port;Set<String> previousOperations=PlanOperations.tokens();Map<String,?> preferences=new HashMap<>(Prefs.of(context).getAll());
            try{
                i.runOnMainSync(()->AutomationActivity.port=fixture);launch();require("My webhook");ruleState(true);String originalRule=store.rows().get(0).id;
                desc("Rule enabled: My webhook");ruleState(false);assertFalse(store.rule(originalRule).enabled);assertEquals(2,store.rule(originalRule).revision);assertEquals("Off",store.rows().get(0).status);assertEquals(0,pending());recreate();ruleState(false);assertFalse(store.rule(originalRule).enabled);
                desc("Rule enabled: My webhook");ruleState(true);assertTrue(store.rule(originalRule).enabled);assertEquals(3,store.rule(originalRule).revision);assertEquals("Ready for new events",store.rows().get(0).status);assertEquals(0,pending());
                i.runOnMainSync(()->{View root=activity.getWindow().getDecorView();for(String label:List.of("My webhook","Tasker","Webhook","MQTT","Add rule"))bounds(root,label,false,true);assertFalse("Independent title and 48dp toggle do not overlap",Rect.intersects(bounds(root,"My webhook",false,true),bounds(root,"Rule enabled: My webhook",true,true)));assertNotNull(find(root,"Tracking starts",false));assertNotNull(find(root,"Webhook",false));bounds(root,"When tracking starts → Webhook; edit My webhook",true,true);});capture("automation-rules-main","Add rule",true);
                // A pending row read cannot override navigation or admit Add while it owns the load.
                blockOpen.set(true);click("My webhook");assertTrue(readStarted.await(5,TimeUnit.SECONDS));i.runOnMainSync(()->assertFalse(find(activity.getWindow().getDecorView(),"Add rule",false).isEnabled()));desc("Automation options");readRelease.countDown();Automations.io.submit(()->{}).get(8,TimeUnit.SECONDS);page("options");assertNull(field("draft"));recreate();page("options");capture("automation-rules-options","Done",true);
                Instrumentation.ActivityMonitor incoming=i.addMonitor(IncomingAutomationSettingsActivity.class.getName(),null,true);try{click("Incoming tracking requests");assertEquals("Actual explicit incoming-settings route; blocked destination",1,incoming.getHits());}finally{i.removeMonitor(incoming);}back();page("home");require("My webhook");click("Webhook");recreate();page("destination");capture("automation-rules-destination","Add Webhook rule",true);click("Add Webhook rule");page("editor");i.runOnMainSync(()->assertFalse(((Switch)find(activity.getWindow().getDecorView(),"Enabled",true)).isChecked()));assertEquals(1,store.rows().size());back();page("home");require("My webhook");
                click("My webhook");page("editor");text("Rule name","Reviewed rule");text("HTTPS URL","https://example.org/pinned");text("Bearer token (optional)","private-unsaved-credential");click("When");page("event");desc("When tracking ends");recreate();page("event");click("Use event");page("editor");click("Destination type");desc("Webhook");recreate();page("transport");capture("automation-rule-type-recreated","Use destination",true);click("Use destination");assertText("Rule name","Reviewed rule");assertText("HTTPS URL","https://example.org/pinned");assertText("Bearer token (optional)","private-unsaved-credential");capture("automation-rule-draft","Save rule",true);assertEquals("My webhook",store.rule(store.rows().get(0).id).name);assertEquals(0,pending());
                desc("Rule options");recreate();page("rule-options");click("Send saved rule’s test event");require("Send test");View oldRoot=focused();View[] oldSend={null};i.runOnMainSync(()->oldSend[0]=find(oldRoot,"Send test",false));recreate();require("Send test");capture("automation-rule-test-confirmation-recreated","Send test",true);i.runOnMainSync(()->oldSend[0].performClick());assertEquals("Destroyed confirmation cannot queue",0,pending());click("Cancel");page("rule-options");assertEquals(0,pending());click("Delete rule");require("Delete rule?");recreate();require("Delete rule?");click("Cancel");page("rule-options");assertEquals("Delete cancellation preserves the saved rule",1,store.rows().size());assertEquals(0,pending());
                blockSchedule.set(true);click("Send saved rule’s test event");require("Send test");click("Send test");assertTrue(scheduleStarted.await(5,TimeUnit.SECONDS));String occurrence=(String)field("testOccurrence");assertFalse(occurrence.isEmpty());recreate();page("rule-options");assertEquals(occurrence,field("testOccurrence"));require("Queueing the reviewed test…");capture("automation-rule-busy-recreated","Done",false);scheduleRelease.countDown();await(()->{boolean[] done={false};i.runOnMainSync(()->done[0]=field("request")==null);return done[0];});require("Test event queued.");assertEquals("Rotation cannot duplicate the accepted private event",1,pending());try(Cursor c=store.getReadableDatabase().rawQuery("SELECT event,event_id,test FROM deliveries WHERE state='pending'",null)){assertTrue(c.moveToFirst());assertEquals("TRACKING_STARTED",c.getString(0));assertEquals(AutomationEvent.occurrence(AutomationEvent.Kind.TRACKING_STARTED,occurrence,1,true).id,c.getString(1));assertEquals(1,c.getInt(2));}
                click("Done");page("editor");assertText("HTTPS URL","https://example.org/pinned");failSchedule.set(true);click("Save rule");page("home");require("Rule saved. Delivery scheduling needs attention. Reopen Automations to retry scheduling.");require("Reviewed rule");assertEquals(0,pending());AutomationRule saved=store.rule(store.rows().get(0).id);assertEquals("Reviewed rule",saved.name);assertEquals("https://example.org/pinned",saved.destination);assertEquals("private-unsaved-credential",saved.secret);assertEquals(AutomationEvent.Kind.TRACKING_STOPPED,saved.event);capture("automation-rules-saved-notice","Add rule",true);
                desc("Automation options");failOpen.set(true);click("Refresh saved rules");require("Rules could not be loaded. Saved rules have not been removed.");capture("automation-rules-load-error","Refresh rules",true);click("Refresh rules");require("Reviewed rule");await(()->{boolean[] clear={false};i.runOnMainSync(()->clear[0]=((String)field("loadFailure")).isEmpty());return clear[0];});click("Reviewed rule");page("editor");assertText("Rule name","Reviewed rule");assertText("Bearer token (optional)","private-unsaved-credential");capture("automation-rule-reopened","Save rule",true);text("Rule name","Discard this draft");back();page("home");require("Reviewed rule");assertEquals("Reviewed rule",store.rule(saved.id).name);assertEquals(0,pending());assertEquals("Only explicit private Off, On, Test and Save schedule",4,schedules.get());assertEquals(10,captures);assertEquals(preferences,Prefs.of(context).getAll());quiet();
            }catch(Exception|AssertionError failure){try{File dir=new File(context.getExternalFilesDir(null),"verification");dir.mkdirs();device.takeScreenshot(new File(dir,"automation-rules-failure.png"));device.dumpWindowHierarchy(new File(dir,"automation-rules-failure.xml"));}catch(Exception ignored){}throw new AssertionError(step,failure);
            }finally{
                readRelease.countDown();scheduleRelease.countDown();i.runOnMainSync(()->{for(AutomationActivity a:activities)if(!a.isDestroyed())a.finish();});await(()->activities.stream().allMatch(Activity::isDestroyed));Automations.io.submit(()->{}).get(8,TimeUnit.SECONDS);PlanOperations.drain(8000);i.waitForIdleSync();for(String token:PlanOperations.tokens())if(!previousOperations.contains(token))PlanOperations.forget(token);i.runOnMainSync(()->AutomationActivity.port=previous);assertEquals(preferences,Prefs.of(context).getAll());quiet();
            }
        }
    }
}
